    "onboarding.vouch.li2": "ཁོང་གིས་རང་གི་ཤོག་ངོས་ཕྱེ་སྟེ་ཁྱེད་ཀྱི་ཆེད་དཔང་པོ་སྣོན།",
    "onboarding.vouch.li3a": "ཁྱེད་ཀྱི་བྱ་སྤྱོད་དང་པོ་ལ་འགྲོ་བའི་དྲ་བའི་གླ་ཆ་ཆུང་ཆུང་དེར, ཁྱེད་ལ་འདེམ་ཁ་ཞིག་ཡོད:",
    "onboarding.vouch.li3b": "ཁྱེད་རང SOL ཏོག་ཙམ་གྱིས, ཡང་ན",
    "onboarding.vouch.li3c": "སྤྱོད — རིན་མེད་ཁ་སྐོང་ཞིག་ཡིན་སྟབས་གླ་ཆ་ནི་གདན་ས་ལ་བར་ཆད་ནམ་ཡང་མིན།",
    "onboarding.vouch.li3faucet": "ཆུ་སྣོད",
    "onboarding.vouch.li3fund": "ཁྱེད་ཀྱི་སྒམ་འཛིན་ལ་དངུལ་བླུགས",
    "onboarding.vouch.p1a": "AHA ལ་ཐོ་འགོད་འཛིན་ཤོག་མེད། ནང་ཡོད་མཁན་ཞིག་གིས་ཁྱེད་ལ་དཔང་པོ་བྱས་སྟབས་ཁྱེད་ཞུགས — ཁྱེད་ཀྱི",
    "onboarding.vouch.p1b": "(རྒྱབ་སྐྱོར་བ)། ཁོང་གིས་ཟིན་བྲིས་ཐོག་གསང་བའི་དཔང་རྟགས་ཤིག་བཀོད་པ་དེས, དོན་དངོས་སུ, འདི་ལྟར་བཤད:",
    "onboarding.vouch.p3a": "དཔང་པོ་དང་ཆུ་སྣོད་གཉིས་ཀ་ཁྱེད་ཀྱི",
    "onboarding.vouch.p3b": "ཤོག་ངོས་ཐོག་ཡོད — གོམ་པ་འདིས་དེ་གཉིས་འཚོལ་མི་དགོས་པར་ཁྱེད་དེར་ཁྲིད།",
    "onboarding.vouch.parrain": "ཕ་རན",
    "onboarding.vouch.quote": "“ང་ལ་མི་འདི་ངོ་ཤེས་ཤིང་ཁོང་འདིར་གནས་འོས།”",
    "onboarding.vouch.readTraditions": "སྲོལ་རྒྱུན་སྐོར་ཀློག",
    "onboarding.vouch.title": "དཔང་པོ་ཐོབ།",
    "onboarding.wallet.ackLabel": "ངས་སྒམ་འཛིན་ཞིག་གྲ་སྒྲིག་བྱས་ཤིང་ངའི་ས་བོན་ཚིག་གྲུབ་བདེ་འཇགས་དང་དྲ་ཐག་མེད་སར་ཟིན་བྲིས་བྱས།",
    "onboarding.wallet.ackedA": "ལེགས། ཁྱེད་ཀྱི་ལྡེ་མིག་ཁྱེད་ཀྱི་ཡིན། མུ་མཐུད་ས",
    "onboarding.wallet.emOnly": "ཁོ་ན",
    "onboarding.wallet.emRecovery": "སོར་ཆུད་ཚིག་གྲུབ",
    "onboarding.wallet.emSeed": "ས་བོན་ཚིག་གྲུབ",
    "onboarding.wallet.notAckedA": "འདི་བྱས་ཚར་རྗེས, གོང་གི་སྒྲོམ་ལ་རྟགས་རྒྱོབ — དེ་ནས་སོང་ས",
    "onboarding.wallet.notAckedB": "དཔང་པོ་ཐོབ་པར།",
    "onboarding.wallet.orWord": "འམ",
    "onboarding.wallet.p1a": "ཁྱེད་ཀྱི་སྒམ་འཛིན་ནི་ཁྱེད་ནང་འཛུལ་བྱེད་ཐབས་ཡིན — སྤྱོད་མིང་ངམ་གསང་ཚིག་མེད། AHA ལ་ཁྱེད་ཡིན་པ་ཤེས་དགོས་སྐབས, ཁྱེད་ཀྱི་སྒམ་འཛིན་གྱིས་ཁྱེད་ལ",
    "onboarding.wallet.p1b": "ཞུ། མཚན་རྟགས་ཀྱིས་ཁྱེད་ལ་ལྡེ་མིག་ཡོད་པ་ར་སྤྲོད; གང་ཡང་མི་འགྲོ་ཞིང་དངུལ་མི་སྤོ།",
    "onboarding.wallet.pickOne": "འོག་ནས་སྒམ་འཛིན་གཅིག་འདེམ་ལ་སྒྲིག་འཇུག། གང་རུང་ལས་ཐུབ།",
    "onboarding.wallet.seedP2a": "ཁྱེད་ཀྱི་སྒམ་འཛིན་གྱིས་ཁྱེད་ལ་གསང་ཚིག་གི་མིང་ཐོ (ཁྱེད་ཀྱི",
    "onboarding.wallet.seedP2b": ") སྟོན་སྐབས, ཤོག་བུ་ལ་བྲིས་ཤིང་བདེ་འཇགས་དང་གསང་བའི་སར་ཉོར། དེ་དག་ནི་ཁྱེད་ཀྱི་རྩིས་ཁྲ་སོར་ཆུད་བྱེད་ཐབས",
    "onboarding.wallet.seedP2c": "ཡིན། སུས་ཀྱང — AHA མིན, ཁྱེད་ཀྱི་རྒྱབ་སྐྱོར་བ་མིན, སྒམ་འཛིན་ཀམ་པ་ཎི་མིན — ཁྱེད་ཀྱི་ཆེད་སོར་ཆུད་མི་ཐུབ། ནམ་ཡང་དྲ་ཚིགས་ལ་མ་འཇུག, ནམ་ཡང་པར་མ་རྒྱོབ, སུས་བཤད་ཀྱང་ནམ་ཡང་མཉམ་སྤྱོད་མ་བྱེད།",
